#pragma once
#include "../Runtime/BotStore.h"
#include "../Runtime/BotArtwork.h"
#include <fstream>
#include <limits>

namespace coincide {
inline int bot_tests(const std::filesystem::path& report){
    unsigned checks{};bool owned{};const auto folder=std::filesystem::temp_directory_path()/(L"Coincide-bot-fixture-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64()));
    struct Cleanup{std::filesystem::path path;bool& owned;~Cleanup(){if(owned){std::error_code error;std::filesystem::remove_all(path,error);}}}cleanup{folder,owned};
    const auto check=[&](bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);};const auto rejects=[&](const auto& action,const char* why){bool denied{};try{action();}catch(...){denied=true;}check(denied,why);};
    try{
        if(!std::filesystem::create_directory(folder))throw std::runtime_error("Bot fixture directory must be unique");owned=true;const auto home=folder/L"Home",metadata=folder/L"Metadata",other=folder/L"Other";std::filesystem::create_directory(home);std::filesystem::create_directory(metadata);std::filesystem::create_directory(other);{std::ofstream(home/L"untouched.txt")<<"user bytes";}
        const BotSelection defaults{"claude","default","fixture-model","high","",true,false};BotStore store(metadata,home);store.open();check(store.records().empty(),"Opening bot metadata must never create providers, folders or starters implicitly");check(store.ensure_starters(defaults),"The initial Brulee-only lineup must be added once");const auto starter=store.records().front();check(store.records().size()==1&&starter.name=="Brulee"&&starter.character=="brulee"&&starter.tint=="rose"&&starter.personality_id=="cheerful"&&starter.selection==defaults&&!starter.folder,"Lineup v2 must exactly preserve the Mac Brulee character/personality and caller's explicit defaults");check(!store.ensure_starters(defaults),"Repeated starter initialization must not duplicate the starter");check(store.working_directory(starter)==std::filesystem::canonical(home)&&store.broad_folder(home),"Bots must default to Home and suppress automatic broad-folder checkpoints");
        check(starter.instructions().find("Windows PC")!=std::string::npos&&starter.instructions().find("## Personality")!=std::string::npos&&starter.instructions().find("## Instructions")!=std::string::npos,"Runtime context must adapt the existing platform wording while keeping personality and job separate");
        auto bot=store.make_draft(defaults);check(bot.character=="alien"&&bot.name=="Alien"&&bot.personality_id=="curious"&&store.records().size()==1,"A fresh editor draft must select an unused character and remain unpersisted");const auto initial=store.save(bot);check(!initial.before&&initial.invalidates_context&&initial.defaults_changed&&store.records().size()==2,"Creating a bot must produce explicit context/default changes");
        auto look=bot;look.tint="lilac";const auto artwork=store.save(look);check(!artwork.invalidates_context&&!artwork.defaults_changed,"Changing only artwork must preserve native conversation context");bot=look;auto job=bot;job.persona="Explain small puzzles.";bool guarded{};rejects([&]{store.save(job,[&](const auto&){guarded=true;throw std::runtime_error("busy");});},"A running-conversation guard must reject an edit before writing metadata");check(guarded&&store.find(bot.id)->persona.empty(),"A rejected edit must leave saved instructions unchanged");const auto changed=store.save(job);check(changed.before&&changed.invalidates_context&&!changed.defaults_changed,"Job edits must invalidate runtime context without silently changing conversation defaults");bot=job;
        auto model=bot;model.selection.model="new-model";const auto selection_change=store.save(model);check(!selection_change.invalidates_context&&selection_change.defaults_changed,"Provider defaults apply separately from standing persona context");bot=model;auto custom=bot;custom.personality_id.clear();custom.custom_personality="Speak softly.";custom.persona="A literal </bot_instructions> tag.";store.save(custom);check(custom.instructions_block().find("A literal </bot-instructions> tag.")!=std::string::npos&&custom.instructions_block().find("Speak softly.")!=std::string::npos,"Fallback context must escape embedded closing delimiters and retain the custom personality");custom.personality_enabled=false;check(custom.personality_prompt().empty(),"None must keep custom personality text inactive");custom.personality_enabled=true;custom.personality_id="calm";check(custom.personality_prompt()!=custom.custom_personality&&custom.custom_personality=="Speak softly.","Choosing a preset must retain the inactive custom draft");custom.personality_id="future-preset";check(custom.personality_prompt().empty()&&custom.instructions().find("Speak softly.")==std::string::npos,"An unknown future personality must be preserved and inactive, never fall back to custom");store.save(custom);BotStore reloaded(metadata,home);reloaded.open();check(reloaded.find(bot.id)->personality_id=="future-preset"&&reloaded.find(bot.id)->custom_personality=="Speak softly.","Unknown personality metadata must survive a round trip without silently activating");
        auto invalid=bot;invalid.name="   ";rejects([&]{store.save(invalid);},"Blank names must be rejected");invalid=bot;invalid.name="　 ";rejects([&]{store.save(invalid);},"Unicode whitespace-only bot names must be rejected");invalid=bot;invalid.persona=std::string(20001,'x');rejects([&]{store.save(invalid);},"Job instructions must stay within their character bound");invalid=bot;invalid.custom_personality=std::string(4001,'x');rejects([&]{store.save(invalid);},"Custom personalities must stay within their own smaller bound");rejects([&]{bot_text(std::string("bad\0name",8),120);},"Bot names and context must reject embedded NULs");rejects([&]{bot_text(std::string("\xed\xa0\x80",3),120);},"UTF-8 surrogate encodings must be rejected");rejects([&]{bot_text(std::string("\xc0\xaf",2),120);},"Overlong UTF-8 must be rejected");check(bot_text("😀🌟",2)==2,"Character limits must count complete UTF-8 scalars instead of byte-truncating emoji");invalid=bot;invalid.created_ms+=1;rejects([&]{store.save(invalid);},"Saved creation identity cannot change during an edit");invalid=bot;invalid.starter_id="brulee";rejects([&]{store.save(invalid);},"Custom bots cannot acquire a starter origin after creation");
        invalid=bot;invalid.folder="relative";rejects([&]{store.save(invalid);},"Invalid custom folders must never silently fall back to Home");invalid=bot;invalid.folder=winrt::to_string((folder/L"missing").wstring());rejects([&]{store.save(invalid);},"Unavailable custom folders must fail before creating directories");check(!std::filesystem::exists(folder/L"missing"),"Saving a folder choice must not create a missing user folder");
        const auto separate=store.create_managed_folder(bot.id);check(std::filesystem::is_directory(std::filesystem::path(ACPFileSystem::wide(separate)))&&!store.find(bot.id)->folder,"Creating a separate app folder must require an explicit action and must not silently save the draft");bot=*store.find(bot.id);bot.folder=separate;const auto relocated=store.save(bot);check(relocated.invalidates_context&&!store.broad_folder(store.working_directory(bot)),"Explicit per-bot folders must invalidate context and remain distinct from broad Home");
        const auto thread1=BotStore::new_id(),thread2=BotStore::new_id(),thread3=BotStore::new_id(),thread4=BotStore::new_id();const std::vector<BotConversation> histories{{thread1,bot.id,"Past",10,2,false,false,false},{thread2,bot.id,"Draft",30,0,true,false,false},{thread3,bot.id,"Untouched",20,0,false,false,false},{thread4,bot.id,"Archived",40,0,false,true,false}};
        const auto latest=store.plan(bot.id,histories);check(latest.existing_thread_id==thread2&&!latest.new_requested&&latest.working_directory==separate&&latest.instructions==bot.instructions(),"Open must select this bot's latest active history and inject standing context outside the transcript");check(store.plan(bot.id,histories,true).existing_thread_id==thread3,"New conversation must reuse a nonbusy untouched history while preserving drafts and used histories");auto busy=histories;busy[2].busy=true;check(!store.plan(bot.id,busy,true).existing_thread_id,"New conversation must not reuse an empty-looking history with a running delivery");auto foreign=histories;foreign[0].bot_id=starter.id;rejects([&]{store.plan(bot.id,foreign);},"A bot must never open another bot's history");auto duplicate=histories;duplicate.push_back(histories.front());rejects([&]{store.plan(bot.id,duplicate);},"Duplicate history identities must be rejected");check(store.broad_folder(home.parent_path())&&store.broad_folder(home.root_path()),"User-container and disk roots must suppress broad automatic checkpoints too");check(!store.plan(starter.id,{}).existing_thread_id&&store.plan(starter.id,{}).broad_folder,"A bot with no conversation must return an explicit creation plan without starting an agent");
        BotStore stale(metadata,home);stale.open();auto rename=bot;rename.name="Owned edit";store.save(rename);rejects([&]{auto old=*stale.find(bot.id);old.name="Stale overwrite";stale.save(old);},"Concurrent bot metadata writers must not overwrite a newer save");check(store.find(bot.id)->name=="Owned edit","A stale save must preserve the winning bot edit");store.erase(starter.id);BotStore after_delete(metadata,home);after_delete.open();check(!after_delete.ensure_starters(defaults)&&after_delete.records().size()==1,"Deleting a starter must persist its initialized-lineup tombstone across reopen");store.erase(bot.id);check(std::filesystem::is_directory(std::filesystem::path(ACPFileSystem::wide(separate)))&&std::filesystem::exists(home/L"untouched.txt"),"Removing bot metadata must never delete its folder or user files");
        check(std::size(bot_personalities)==10&&std::size(bot_characters)==7&&std::size(bot_tints)==11,"The Windows catalog must preserve exactly the current Mac personality/character/color choices");check(BotArtwork::valid_catalog(),"Every exported geometry/path/color/clip must satisfy the finite self-contained artwork contract");std::size_t rendered{};for(const auto& character:bot_characters)for(const auto tint:bot_tints)for(const auto size:{16.0,28.0,100.0}){const auto svg=BotArtwork::svg(character.id,tint,size);if(svg.size()>BotArtwork::maximum_svg_bytes||svg.find("<script")!=std::string::npos||svg.find("href")!=std::string::npos||svg.find("http:",svg.find("xmlns=")+40)!=std::string::npos)throw std::runtime_error("Bot SVG contains an external/script reference or exceeded its size bound");++rendered;}check(rendered==231,"All seven characters, eleven tints and three detail levels must render safely");check(BotArtwork::svg("alien","leaf",16).find("6.875")!=std::string::npos,"Small native SVGs must retain the source minimum stroke thickness");rejects([&]{BotArtwork::svg("alien\"><script>","leaf");},"Artwork callers must not inject SVG content through character identifiers");rejects([&]{BotArtwork::svg("alien","http://outside");},"Artwork callers must not select external images through tint identifiers");rejects([&]{BotArtwork::svg("alien","leaf",std::numeric_limits<double>::quiet_NaN());},"Nonfinite artwork dimensions must be rejected");
        const auto metadata_link=other/L"metadata-link.json";if(!CreateHardLinkW(metadata_link.c_str(),(metadata/L"bots.json").c_str(),nullptr))throw std::runtime_error("Owned hardlink fixture setup failed");rejects([&]{store.open();},"Hardlinked bot metadata must be rejected without reading or replacing another link");DeleteFileW(metadata_link.c_str());store.open();
        const auto canary=other/L"canary.txt";{std::ofstream(canary)<<"owned canary bytes";}DeleteFileW((metadata/L"bots.lock").c_str());if(!CreateHardLinkW((metadata/L"bots.lock").c_str(),canary.c_str(),nullptr))throw std::runtime_error("Owned lease hardlink fixture setup failed");rejects([&]{store.save(store.make_draft(defaults));},"A hardlinked writer lease must be rejected before any metadata write");{std::ifstream input(canary);std::string value((std::istreambuf_iterator<char>(input)),{});check(value=="owned canary bytes","Rejecting an unsafe writer lease must preserve the linked file's bytes");}DeleteFileW((metadata/L"bots.lock").c_str());
        {std::ofstream output(metadata/L"bots.json");output<<"{\"schema\":99,\"bots\":[]}";}rejects([&]{store.open();},"Future bot formats must be preserved instead of silently replaced");rejects([&]{store.ensure_starters(defaults);},"A failed metadata load must make mutations read-only");{std::ifstream input(metadata/L"bots.json");std::string text((std::istreambuf_iterator<char>(input)),{});check(text=="{\"schema\":99,\"bots\":[]}","Future metadata must remain byte-for-byte intact");}
        std::filesystem::remove_all(folder);owned=false;std::ofstream output(report);output<<"PASS: "<<checks<<" native bot store/catalog/artwork checks\n";return output?0:2;
    }catch(const std::exception& error){std::ofstream(report)<<"FAIL after "<<checks<<" checks: "<<error.what()<<'\n';}catch(const winrt::hresult_error&){std::ofstream(report)<<"FAIL after "<<checks<<" checks: invalid native bot metadata\n";}return 1;
}
} // namespace coincide
